export function sortedSquares(nums: number[]): number[] {
  const n = nums.length;
  const result = new Array<number>(n);
  let left = 0;
  let right = n - 1;
  let pos = n - 1;
  while (left <= right) {
    if (Math.abs(nums[left]) > Math.abs(nums[right])) {
      result[pos] = nums[left] ** 2;
      left++;
    } else {
      result[pos] = nums[right] ** 2;
      right--;
    }
    pos--;
  }
  return result;
}
